#!/usr/bin/env julia
#       $Id$
#  D. Sandwell 1/12/07
#  M. Wei 1/31/08
#
# alias rm 'rm -f'
# unset noclobber

function main(argv::Vector{String})
    local V::Vector{String}
    if isfile(joinpath(homedir(), ".quiet"))
        V = String[]
    else
        V = ["-V"]
    end

    #
    #
    #  project an xy file from lon/lat coordinates into range/azimuth coordinates
    #  this version only works with GMT V4.0 and higher
    #
    #  Input:
    #  trans.dat    - file generated by llt_grid2rat  (r a topo lon lat)
    #  phase_ll.xyz - an ascii file of phase or anything in longitude/latitude coordinates
    #
    #  Output:
    #  phase_ra.zyz - an ascii file of phase in radar coordinates
    #
    # check for number of arguments
    #
    if length(argv) < 3
        println(" ")
        println("Usage: proj_ll2ra_ascii.csh trans.dat phase_ll.xyz phase_ra.xyz")
        println(" ")
        println("        trans.dat    - file generated by llt_grid2rat  (r a topo lon lat)")
        println("        phase_ll.xyz - an Ascii file of phase or anything in lon/lat-coordinates")
        println("        phase_ra.xyz - output an Ascii file in radar coordinates")
        println(" ")
        exit(1)
    end
    #
    #  extract the phase in the r a positions
    #
    #   make grids of longitude and latitude versus range and azimuth
    #
    run(pipeline(`gmt gmtconvert $(argv[1]) -o3,4,0 -bi5d -bo3f`, stdout="llr"))
    run(pipeline(`gmt gmtconvert $(argv[1]) -o3,4,1 -bi5d -bo3f`, stdout="lla"))
    #awk '{ printf("%f %f %e \n",$4,$5,$1) }' < $1 | gmtconvert -bos3 > llr
    #awk '{ printf("%f %f %e \n",$4,$5,$2) }' < $1 | gmtconvert -bos3 > lla
    #
    ginfo1 = strip(read(`gmt gmtinfo $(argv[2]) -I0.01`, String))
    run(`gmt surface llr $ginfo1 -bi3f -I0.005 -T.50 -Gllr.grd $V`)
    ginfo2 = strip(read(`gmt gmtinfo $(argv[2]) -I0.01`, String))
    run(`gmt surface lla $ginfo2 -bi3f -I0.005 -T.50 -Glla.grd $V`)
    #
    run(pipeline(`gmt grdtrack $(argv[2]) -nl -Gllr.grd`, stdout="llpr"))
    run(pipeline(`gmt grdtrack llpr -nl -Glla.grd`, stdout="llpra"))
    #
    # get the range, azimuth, phase columns and grid
    #
    open(argv[3], "w") do io
        for line in readlines("llpra")
            w = split(line)
            println(io, "$(w[4]) $(w[5]) $(w[3])")
        end
    end
    #
    #
    #
    # clean
    #
    for f in readdir(".")
        if startswith(f, "ll")
            rm(f; force=true)
        end
    end
end

main(filter(!isempty, ARGS))   # csh drops empty (unset) arguments
